/* ------------------------------------------------------------------
 * Greenfratech standalone runtime.
 *
 * 1. publicWidget shim  -- runs the theme's four widgets without Odoo.
 * 2. nav               -- the dropdown + offcanvas the header needs.
 *
 * Generated by tools/export_static.py. Edit that, not this.
 * ------------------------------------------------------------------ */
(function () {
    "use strict";

    // --- 1. publicWidget shim ---------------------------------------------
    //
    // The theme's widgets use exactly three things: `selector`, `this.el`, and
    // `this._super(...)` inside start()/destroy(). No jQuery, no event maps, no
    // `this.$el`. So the whole framework reduces to: prototype chaining with a
    // working _super, plus a bootstrapper that matches selectors on load.
    function makeSuper(name, fn, parentProto) {
        return function () {
            var prev = this._super;
            var self = this;
            this._super = function () {
                var pf = parentProto[name];
                // The real base start() returns a Promise; destroy() returns
                // nothing. Mirroring that keeps `return this._super(...)` valid.
                return pf ? pf.apply(self, arguments) : Promise.resolve();
            };
            try {
                return fn.apply(this, arguments);
            } finally {
                this._super = prev;
            }
        };
    }

    function extend(proto) {
        var parentProto = this.prototype;
        function Widget(el) { this.el = el; }
        Widget.prototype = Object.create(parentProto);
        Object.keys(proto).forEach(function (key) {
            var val = proto[key];
            // Only wrap functions that actually reach for _super, so ordinary
            // methods keep their own `this` handling untouched.
            if (typeof val === 'function' && /\b_super\b/.test(String(val))) {
                Widget.prototype[key] = makeSuper(key, val, parentProto);
            } else {
                Widget.prototype[key] = val;
            }
        });
        Widget.extend = extend;
        return Widget;
    }

    function Base() {}
    Base.prototype.start = function () { return Promise.resolve(); };
    Base.prototype.destroy = function () {};
    Base.extend = extend;

    var publicWidget = { registry: {}, Widget: Base };
    window.publicWidget = publicWidget;

    // --- 2. header nav ----------------------------------------------------
    function closeDropdowns(except) {
        document.querySelectorAll('.dropdown-toggle.show').forEach(function (t) {
            if (t === except) { return; }
            t.classList.remove('show');
            t.setAttribute('aria-expanded', 'false');
            var m = t.parentElement && t.parentElement.querySelector('.dropdown-menu');
            if (m) { m.classList.remove('show'); }
        });
    }

    function initNav() {
        document.querySelectorAll('[data-bs-toggle="dropdown"]').forEach(function (t) {
            t.addEventListener('click', function (ev) {
                ev.preventDefault();
                ev.stopPropagation();
                var menu = t.parentElement && t.parentElement.querySelector('.dropdown-menu');
                var open = t.classList.contains('show');
                closeDropdowns(t);
                t.classList.toggle('show', !open);
                t.setAttribute('aria-expanded', String(!open));
                if (menu) { menu.classList.toggle('show', !open); }
            });
        });
        document.addEventListener('click', function () { closeDropdowns(null); });
        document.addEventListener('keydown', function (ev) {
            if (ev.key === 'Escape') { closeDropdowns(null); hideOffcanvas(); }
        });

        document.querySelectorAll('[data-bs-toggle="offcanvas"]').forEach(function (btn) {
            btn.addEventListener('click', function (ev) {
                ev.preventDefault();
                var sel = btn.getAttribute('data-bs-target');
                var panel = sel && document.querySelector(sel);
                if (panel) { showOffcanvas(panel); }
            });
        });
        document.querySelectorAll('[data-bs-dismiss="offcanvas"]').forEach(function (btn) {
            btn.addEventListener('click', function (ev) {
                ev.preventDefault();
                hideOffcanvas();
            });
        });
        // A tap on any nav link inside the panel should also close it, or the
        // panel stays over the page it just navigated to.
        document.querySelectorAll('.offcanvas a[href]').forEach(function (a) {
            a.addEventListener('click', function () {
                if (!a.classList.contains('dropdown-toggle')) { hideOffcanvas(); }
            });
        });
    }

    function showOffcanvas(panel) {
        var back = document.createElement('div');
        back.className = 'offcanvas-backdrop show';
        back.setAttribute('data-gft-backdrop', '');
        back.addEventListener('click', hideOffcanvas);
        document.body.appendChild(back);
        document.body.style.overflow = 'hidden';
        panel.classList.add('show');
        panel.removeAttribute('aria-hidden');
    }

    function hideOffcanvas() {
        document.querySelectorAll('.offcanvas.show').forEach(function (p) {
            p.classList.remove('show');
            p.setAttribute('aria-hidden', 'true');
        });
        document.querySelectorAll('[data-gft-backdrop]').forEach(function (b) {
            b.remove();
        });
        document.body.style.overflow = '';
    }

    // Odoo's fixed-header widget, reduced to what this theme needs: every page
    // uses the overlay header, so affixing it is just a class swap from
    // position: absolute to position: fixed once the page leaves the top.
    function initFixedHeader() {
        var header = document.querySelector('#wrapwrap > header.o_header_fixed');
        if (!header) { return; }
        var apply = function () {
            var y = window.scrollY || document.documentElement.scrollTop || 0;
            var affixed = y > 0;
            header.classList.toggle('o_header_affixed', affixed);
            header.classList.toggle('o_top_fixed_element', affixed);
            header.classList.toggle('o_header_is_scrolled', affixed);
        };
        window.addEventListener('scroll', apply, { passive: true });
        apply();
    }

    // --- 3. boot ----------------------------------------------------------
    function boot() {
        initNav();
        initFixedHeader();
        Object.keys(publicWidget.registry).forEach(function (name) {
            var W = publicWidget.registry[name];
            var sel = W.prototype && W.prototype.selector;
            if (!sel) { return; }
            document.querySelectorAll(sel).forEach(function (el) {
                try {
                    new W(el).start();
                } catch (e) {
                    // A broken widget must not take the rest of the page with
                    // it -- the site reads fine without any of them.
                    console.error('[gft] widget ' + name + ' failed', e);
                }
            });
        });
    }

    // Never boot synchronously: the widgets register themselves in the IIFE
    // below this one, so booting here would find an empty registry. That is
    // exactly what happens under `defer`, where readyState is already
    // "interactive" by the time this runs.
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
    } else {
        setTimeout(boot, 0);
    }
})();

(function (publicWidget) {
"use strict";

/**
 * Greenfratech — scroll engine.
 *
 * Two public widgets:
 *
 *   GftChrome   site-wide. Marks the document as JS-capable, drives the
 *               transparent-to-glass navbar, runs the reveal-on-scroll
 *               observer, and defuses the overflow trap that would silently
 *               kill position: sticky.
 *
 *   GftStage    the homepage's pinned 3D stage. Maps scroll progress onto two
 *               CSS custom properties and a data-beat attribute; every
 *               transform is then derived in CSS.
 *
 * Both are publicWidget.Widget subclasses, so they inherit
 * `disabledInEditableMode: true` from website's include: neither runs inside
 * the website builder. That is deliberate. A rAF loop rewriting transforms
 * fights the editor's drag-and-drop hit-testing, and a sticky pin fights its
 * scroll handling. In edit mode the stage falls back to its flat layout, which
 * shows every beat at once — exactly what you want when editing copy.
 *
 * Design rules this file sticks to:
 *
 *   * Progress is computed from getBoundingClientRect() and innerHeight only,
 *     never window.scrollY. That is correct regardless of which ancestor is the
 *     scroll container.
 *   * The DOM is read once per frame and written once per frame. No interleaving,
 *     so no forced synchronous layout.
 *   * Nothing is indexed positionally. Layer and beat counts are read from the
 *     DOM, and a missing node degrades instead of throwing — the builder is
 *     allowed to delete things.
 */

// Mirrors $gft-bp-lg in theme.scss. This is a LAYOUT switch, not an on/off
// switch: at and above it the stage is a two-column composition (copy one side,
// slab the other); below it the same mechanic runs in a single column with a
// much smaller slab and cheaper compositing, as .gft-stage--compact.
//
// It used to be the gate — below 992px the stage never pinned and the loop never
// started, on the grounds that a 560vh sticky stage compositing six preserve-3d
// planes was more than a mid-range phone could afford. That is true of the
// desktop scene, but it is a property of the scene, not of the mechanic: the
// cost is dominated by re-rasterising each slab as the perspective scale changes
// it, and the compact scene cuts the slab to ~a fifth of the area, drops the
// blurred shadow and glow, and halves the depth range. See section 09 of
// theme.scss for the full list.
const COMPACT_QUERY = "(max-width: 991.98px)";

// The real constraint on pinning is HEIGHT, not device width: the stage has to
// fit a slab and the paragraph describing it inside one sticky viewport. Below
// this it does not fit at any type size, so the stage falls back to its flat
// flow document. That covers landscape phones and short desktop windows alike.
const PIN_HEIGHT_QUERY = "(min-height: 560px)";

const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

// Beat boundaries as a share of stage progress. The brief called for five
// beats; this is seven: EV Sun and Green Cleaning were split so two products
// no longer compete for one slab, and Infra AI was added as the top layer.
//
//   0  0-11    hero
//   1  11-28   bamboo geotextile
//   2  28-44   green road
//   3  44-59   water solutions
//   4  59-73   sterilization lighting
//   5  73-87   green cleaning
//   6  87-100  infra AI + closing CTA
//
// A new beat needs a stop here, a data-beat rule set in the stylesheet, a
// layer and a beat in the markup, and STACK_CENTRE moved if the layer count
// changes.
const BEAT_STOPS = [0.11, 0.28, 0.44, 0.59, 0.73, 0.87];

// Middle of the layer stack (layers 0-6). Mirrors the 3 in the stylesheet's
// camera and layer translateZ; the hero frames the whole stack from here.
const STACK_CENTRE = 3;

// Where the navbar turns to glass. The brief says "after slight scroll", not
// "immediately" — which is why this does not reuse Odoo's o_header_is_scrolled.
const NAV_SOLID_AT = 72;

const lerp = (from, to, t) => from + (to - from) * t;
const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);

/**
 * Explode amount for a given progress: hold assembled, pull apart, hold
 * exploded, glide back together. The brief's "slow, professional disassembly
 * ... then components gracefully glide back into place".
 *
 * @param {number} p progress through the stage, 0 to 1
 * @returns {number} 0 (assembled) to 1 (fully exploded)
 */
function explodeAmount(p) {
    // Thresholds track BEAT_STOPS: fully exploded before beat 1 gets going, and
    // holding until the last beat (6) starts closing it.
    if (p < 0.08) { return 0; }
    if (p < 0.24) { return (p - 0.08) / 0.16; }
    if (p < 0.87) { return 1; }
    if (p < 0.98) { return 1 - (p - 0.87) / 0.11; }
    return 0;
}

/**
 * @param {number} p progress through the stage, 0 to 1
 * @returns {number} index of the active beat
 */
function beatIndex(p) {
    for (let i = 0; i < BEAT_STOPS.length; i++) {
        if (p < BEAT_STOPS[i]) { return i; }
    }
    return BEAT_STOPS.length;
}

//------------------------------------------------------------------------------
// Site-wide chrome
//------------------------------------------------------------------------------

publicWidget.registry.GftChrome = publicWidget.Widget.extend({
    selector: "#wrapwrap",

    /**
     * @override
     */
    start() {
        this.reduced = window.matchMedia(REDUCED_MOTION_QUERY).matches;

        // Tells the stylesheet that JS is alive, so .gft-reveal may start
        // hidden. Without this class the reveal system resolves to its visible
        // end state and a script failure can never blank the page.
        document.documentElement.classList.add("gft-js");

        this._guardBodyOverflow();
        this._watchScroll();
        this._observeReveals();

        return this._super(...arguments);
    },

    /**
     * @override
     */
    destroy() {
        if (this._navObserver) { this._navObserver.disconnect(); }
        if (this._revealObserver) { this._revealObserver.disconnect(); }
        if (this._onScroll) {
            window.removeEventListener("scroll", this._onScroll);
        }
        document.documentElement.classList.remove("gft-js");
        this._super(...arguments);
    },

    /**
     * `overflow-x: hidden` on <body> computes overflow-y to `auto`, which turns
     * <body> into a scroll container — and a position: sticky element inside a
     * scroll container that never itself scrolls simply never sticks.
     *
     * theme_aceme_2's scroll_split.js sets exactly that on every page it runs
     * on, and it initialises on `load` just like this widget, so the ordering
     * between them is not guaranteed. Rewriting `hidden` to `clip` keeps the
     * intent (no horizontal scrollbar) without the side effect. Repeated once
     * asynchronously to cover the case where the other script wins the race.
     *
     * @private
     */
    _guardBodyOverflow() {
        const fix = () => {
            const body = document.body;
            if (!body) { return; }
            if (window.getComputedStyle(body).overflowX === "hidden") {
                body.style.overflowX = "clip";
            }
        };
        fix();
        window.setTimeout(fix, 0);
    },

    /**
     * Toggles the glass navbar. Uses an IntersectionObserver against a sentinel
     * rather than a scroll listener where possible, so the common case costs no
     * main-thread work at all; the scroll listener is only the fallback for
     * browsers without IntersectionObserver.
     *
     * @private
     */
    _watchScroll() {
        this.header = document.querySelector("#wrapwrap > header");
        if (!this.header) { return; }

        const apply = (solid) => {
            this.header.classList.toggle("gft-nav-solid", solid);
        };

        if (window.IntersectionObserver) {
            const sentinel = document.createElement("div");
            sentinel.className = "gft-nav-sentinel";
            sentinel.setAttribute("aria-hidden", "true");
            sentinel.style.top = `${NAV_SOLID_AT}px`;
            // Injected in readonly mode only (this widget never runs in the
            // editor), so it can never be saved into a view.
            this.el.prepend(sentinel);
            this._sentinel = sentinel;

            this._navObserver = new window.IntersectionObserver(
                (entries) => entries.forEach((e) => apply(!e.isIntersecting)),
                { root: null, threshold: 0 }
            );
            this._navObserver.observe(sentinel);
            return;
        }

        this._onScroll = () => {
            const y = window.scrollY || document.documentElement.scrollTop || 0;
            apply(y > NAV_SOLID_AT);
        };
        window.addEventListener("scroll", this._onScroll, { passive: true });
        this._onScroll();
    },

    /**
     * Reveal-once on entry. Elements are never re-hidden, so scrolling back up
     * does not replay anything — the brief rules out "heavy, obvious"
     * animation.
     *
     * @private
     */
    _observeReveals() {
        const targets = this.el.querySelectorAll(".gft-reveal");
        if (!targets.length) { return; }

        if (this.reduced || !window.IntersectionObserver) {
            targets.forEach((el) => el.classList.add("is-in"));
            return;
        }

        this._revealObserver = new window.IntersectionObserver((entries, obs) => {
            entries.forEach((entry) => {
                if (!entry.isIntersecting) { return; }
                entry.target.classList.add("is-in");
                obs.unobserve(entry.target);
            });
        }, { root: null, rootMargin: "0px 0px -12% 0px", threshold: 0.05 });

        targets.forEach((el) => this._revealObserver.observe(el));
    },
});

//------------------------------------------------------------------------------
// The pinned 3D stage
//------------------------------------------------------------------------------

publicWidget.registry.GftStage = publicWidget.Widget.extend({
    selector: "[data-gft-stage]",

    /**
     * @override
     */
    start() {
        this.layers = [...this.el.querySelectorAll("[data-gft-layer]")];
        this.beats = [...this.el.querySelectorAll("[data-gft-beat]")];

        // The builder is allowed to delete things. Nothing here assumes a fixed
        // count, and with no beats at all there is nothing to drive.
        if (!this.beats.length) {
            return this._super(...arguments);
        }

        this.compactMq = window.matchMedia(COMPACT_QUERY);
        this.pinMq = window.matchMedia(PIN_HEIGHT_QUERY);
        this.reducedMq = window.matchMedia(REDUCED_MOTION_QUERY);

        this.progress = 0;
        this.explode = 0;
        this.focus = STACK_CENTRE;
        this.beat = -1;
        this.visible = false;
        this.raf = null;

        this._onModeChange = this._onModeChange.bind(this);
        this._frame = this._frame.bind(this);

        this._addMqListener(this.compactMq);
        this._addMqListener(this.pinMq);
        this._addMqListener(this.reducedMq);

        this._setMode();
        this._observeVisibility();

        return this._super(...arguments);
    },

    /**
     * @override
     */
    destroy() {
        this._stop();
        if (this._visObserver) { this._visObserver.disconnect(); }
        this._removeMqListener(this.compactMq);
        this._removeMqListener(this.pinMq);
        this._removeMqListener(this.reducedMq);
        if (this.el) {
            this.el.classList.remove(
                "gft-stage--pinned", "gft-stage--flow", "gft-stage--compact"
            );
            this.el.style.removeProperty("--gft-p");
            this.el.style.removeProperty("--gft-e");
            this.el.style.removeProperty("--gft-focus");
            this.el.removeAttribute("data-beat");
        }
        this._super(...arguments);
    },

    //--------------------------------------------------------------------------
    // Mode
    //--------------------------------------------------------------------------

    /**
     * `pinned` wherever the viewport is tall enough to hold the composition,
     * `flow` where it is not, and the flat default under reduced motion. Mode is
     * a decision, not a CSS-only degradation: outside `pinned` the animation
     * loop never starts, so a viewport that cannot use it pays nothing.
     *
     * Note this no longer tests WIDTH. Width picks the layout (see
     * _isCompact), not whether the mechanic runs at all.
     *
     * @private
     * @returns {string}
     */
    _mode() {
        if (this.reducedMq.matches) { return "static"; }
        return this.pinMq.matches ? "pinned" : "flow";
    },

    /**
     * One column plus a small slab, versus the two-column desktop composition.
     * Only meaningful while pinned.
     *
     * @private
     * @returns {boolean}
     */
    _isCompact() {
        return this.compactMq.matches;
    },

    /**
     * @private
     */
    _setMode() {
        const mode = this._mode();
        const compact = this._isCompact();

        // Both are compared: rotating a phone can change the layout without
        // changing the mode, and changing the layout changes the stage's height,
        // which invalidates the current progress.
        if (mode === this.mode && compact === this.compact) { return; }
        this.mode = mode;
        this.compact = compact;

        this.el.classList.toggle("gft-stage--pinned", mode === "pinned");
        this.el.classList.toggle("gft-stage--flow", mode === "flow");
        this.el.classList.toggle("gft-stage--compact", mode === "pinned" && compact);

        if (mode === "pinned") {
            this._tick(true);
            this._maybeStart();
        } else {
            this._stop();
            // Leave no inline state behind for the other modes to inherit.
            this.el.style.removeProperty("--gft-p");
            this.el.style.removeProperty("--gft-e");
            this.el.style.removeProperty("--gft-focus");
            this.el.removeAttribute("data-beat");
            this.progress = this.explode = 0;
            this.focus = STACK_CENTRE;
            this.beat = -1;
        }
    },

    /**
     * @private
     */
    _onModeChange() {
        this._setMode();
    },

    //--------------------------------------------------------------------------
    // Visibility
    //--------------------------------------------------------------------------

    /**
     * The loop only runs while the stage is on screen. rootMargin warms it up
     * just before it arrives so the first visible frame is already correct.
     *
     * @private
     */
    _observeVisibility() {
        if (!window.IntersectionObserver) {
            this.visible = true;
            this._maybeStart();
            return;
        }

        this._visObserver = new window.IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                this.visible = entry.isIntersecting;
                if (this.visible) {
                    this._maybeStart();
                } else {
                    this._stop();
                }
            });
        }, { root: null, rootMargin: "25% 0px 25% 0px", threshold: 0 });

        this._visObserver.observe(this.el);
    },

    //--------------------------------------------------------------------------
    // Loop
    //--------------------------------------------------------------------------

    /**
     * @private
     */
    _maybeStart() {
        if (this.raf === null && this.visible && this.mode === "pinned") {
            this.raf = window.requestAnimationFrame(this._frame);
        }
    },

    /**
     * @private
     */
    _stop() {
        if (this.raf !== null) {
            window.cancelAnimationFrame(this.raf);
            this.raf = null;
        }
    },

    /**
     * @private
     */
    _frame() {
        this.raf = null;
        this._tick(false);
        this._maybeStart();
    },

    /**
     * Scroll progress through the stage.
     *
     * Deliberately derived from the element's own rect and the viewport height
     * rather than from window.scrollY: both values are viewport-relative, so
     * this stays correct whichever ancestor happens to be the scroll container
     * — a thing Odoo itself cannot assume (see web's getScrollingElement).
     *
     * @private
     * @returns {number} 0 to 1
     */
    _stageProgress() {
        const rect = this.el.getBoundingClientRect();
        const travel = rect.height - window.innerHeight;
        if (travel <= 0) { return 0; }
        return clamp01(-rect.top / travel);
    },

    /**
     * One read, then all writes. Values are eased toward their targets so the
     * motion keeps the brief's "smooth, buttery" quality even when the scroll
     * itself is coarse (a mouse wheel steps in large jumps).
     *
     * @private
     * @param {boolean} immediate skip easing, e.g. on the first frame
     */
    _tick(immediate) {
        const target = this._stageProgress();
        const targetExplode = explodeAmount(target);

        this.progress = immediate ? target : lerp(this.progress, target, 0.14);
        this.explode = immediate ? targetExplode : lerp(this.explode, targetExplode, 0.10);

        // Snap once the difference stops being visible, so the loop settles on
        // exact end values instead of asymptotically approaching them.
        if (Math.abs(target - this.progress) < 0.0005) { this.progress = target; }
        if (Math.abs(targetExplode - this.explode) < 0.0005) { this.explode = targetExplode; }

        // data-beat is driven by the raw target, not the eased value: the copy
        // should change when the reader has scrolled there, not a moment later.
        const beat = beatIndex(target);

        // The camera's focus layer is eased here rather than by a CSS transition
        // on the camera. Its transform also depends on --gft-p and --gft-e, which
        // change every frame, so a transition there restarted on every frame and
        // made the slab bounce. Beat 0 (hero) frames the middle of the stack.
        const targetFocus = beat === 0 ? STACK_CENTRE : beat;
        this.focus = immediate ? targetFocus : lerp(this.focus, targetFocus, 0.12);
        if (Math.abs(targetFocus - this.focus) < 0.001) { this.focus = targetFocus; }

        this.el.style.setProperty("--gft-p", this.progress.toFixed(4));
        this.el.style.setProperty("--gft-e", this.explode.toFixed(4));
        this.el.style.setProperty("--gft-focus", this.focus.toFixed(4));

        if (beat !== this.beat) {
            this.beat = beat;
            this.el.setAttribute("data-beat", String(beat));
        }
    },

    //--------------------------------------------------------------------------
    // matchMedia helpers
    //--------------------------------------------------------------------------

    /**
     * Safari below 14 only supports the deprecated addListener form.
     *
     * @private
     * @param {MediaQueryList} mq
     */
    _addMqListener(mq) {
        if (mq.addEventListener) {
            mq.addEventListener("change", this._onModeChange);
        } else if (mq.addListener) {
            mq.addListener(this._onModeChange);
        }
    },

    /**
     * @private
     * @param {MediaQueryList} mq
     */
    _removeMqListener(mq) {
        if (!mq) { return; }
        if (mq.removeEventListener) {
            mq.removeEventListener("change", this._onModeChange);
        } else if (mq.removeListener) {
            mq.removeListener(this._onModeChange);
        }
    },
});

//------------------------------------------------------------------------------
// Reversible in-view toggle
//------------------------------------------------------------------------------

// Adds and REMOVES `is-in` as a section enters and leaves the viewport, so the
// stylesheet can animate a section in both directions.
//
// Deliberately separate from the .gft-reveal system in GftChrome, which is
// one-way: reveal unobserves after the first entry precisely so nothing
// replays on the way back up, and that is the right default for body copy. This
// is for the few sections where the animation IS the point and should run every
// time. A section uses one or the other, never both — reveal pins opacity to 1
// permanently and would override the out-state.
//
// Carries no animation of its own. What moves, and how far, is entirely in the
// stylesheet under `html.gft-js [data-gft-inview]:not(.is-in)`, so a new
// section needs one attribute here and a rule there.
publicWidget.registry.GftInView = publicWidget.Widget.extend({
    selector: "[data-gft-inview]",

    /**
     * @override
     */
    start() {
        // Under reduced motion, or with no observer, the section is simply
        // present. Adding the class rather than leaving it off matters: the
        // out-state is the CSS default, so without this the content would stay
        // hidden for exactly the users who cannot see it move.
        if (window.matchMedia(REDUCED_MOTION_QUERY).matches
            || !window.IntersectionObserver) {
            this.el.classList.add("is-in");
            return this._super(...arguments);
        }

        // Same margin as the impact counters: pull the trigger inside the
        // viewport edges so entering and leaving are not the same boundary and
        // a section parked at the edge cannot flicker on one-pixel scrolls.
        this.observer = new window.IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                this.el.classList.toggle("is-in", entry.isIntersecting);
            });
        }, { threshold: 0, rootMargin: "-10% 0px -10% 0px" });

        this.observer.observe(this.el);
        return this._super(...arguments);
    },

    /**
     * @override
     */
    destroy() {
        if (this.observer) { this.observer.disconnect(); }
        // Leave the content visible, not mid-animation.
        if (this.el) { this.el.classList.add("is-in"); }
        this._super(...arguments);
    },
});

//------------------------------------------------------------------------------
// The impact counters
//------------------------------------------------------------------------------

// Counting up reads as achievement; counting back down is just a rewind, so it
// gets a shorter, plainer trip.
const COUNT_IN_MS = 1200;
const COUNT_OUT_MS = 550;

const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);

publicWidget.registry.GftImpact = publicWidget.Widget.extend({
    selector: "[data-gft-impact]",

    /**
     * @override
     */
    start() {
        this.figures = [...this.el.querySelectorAll(".gft-stat__value")]
            .map((el) => this._parse(el))
            .filter(Boolean);

        if (!this.figures.length) {
            return this._super(...arguments);
        }

        this.progress = 0;
        this.raf = null;

        // Under reduced motion the numbers are simply correct and the heading
        // never leaves its place. No observer, no loop, nothing to reverse.
        if (window.matchMedia(REDUCED_MOTION_QUERY).matches) {
            this.progress = 1;
            this._paint();
            this.el.classList.add("is-in");
            return this._super(...arguments);
        }

        this._paint();   // start at zero

        if (!window.IntersectionObserver) {
            this.progress = 1;
            this._paint();
            this.el.classList.add("is-in");
            return this._super(...arguments);
        }

        // No unobserve, unlike the reveal system: this has to fire every time
        // the section enters OR leaves, for as long as the page is open.
        //
        // The margin pulls the trigger inside the viewport edges so the run
        // starts once the section is properly on screen rather than the instant
        // its first pixel appears, and — more importantly — so entering and
        // leaving are not the same boundary. Without it a section parked at the
        // very edge of the viewport can flip in and out on one-pixel scrolls.
        this.observer = new window.IntersectionObserver((entries) => {
            entries.forEach((entry) => {
                this.el.classList.toggle("is-in", entry.isIntersecting);
                this._run(entry.isIntersecting ? 1 : 0);
            });
        }, { threshold: 0, rootMargin: "-12% 0px -12% 0px" });

        this.observer.observe(this.el);

        return this._super(...arguments);
    },

    /**
     * @override
     */
    destroy() {
        if (this.observer) { this.observer.disconnect(); }
        if (this.raf !== null) { window.cancelAnimationFrame(this.raf); }
        // Leave the real figures behind, not whatever frame we stopped on.
        if (this.figures) {
            this.figures.forEach((f) => { f.el.textContent = f.raw; });
        }
        this._super(...arguments);
    },

    /**
     * Reads the target out of the rendered text rather than a data attribute,
     * so the markup stays the single source of truth: edit "45%" to "60%" in
     * the website builder and the count follows it, and with JS disabled the
     * real figures are what the page shows.
     *
     * Handles the prefix/suffix and thousands grouping the copy actually uses
     * ("45%", "500,000"), and returns null for anything it cannot read so a
     * non-numeric stat is simply left alone.
     *
     * @private
     */
    _parse(el) {
        const raw = el.textContent.trim();
        const match = raw.match(/^(\D*?)([\d.,]+)(\D*)$/);
        if (!match) { return null; }

        const [, prefix, body, suffix] = match;
        const target = parseInt(body.replace(/\D/g, ""), 10);
        if (!Number.isFinite(target)) { return null; }

        const grouped = body.includes(",");
        return {
            el, raw, target,
            format: (n) => prefix + (grouped ? n.toLocaleString("en-US") : String(n)) + suffix,
        };
    },

    /**
     * @private
     * @param {number} toward 1 entering, 0 leaving
     */
    _run(toward) {
        if (this.raf !== null) { window.cancelAnimationFrame(this.raf); }

        const from = this.progress;
        if (from === toward) { return; }

        // Scale the duration to the distance left to travel, so reversing
        // mid-flight does not take a full trip to cover a short gap.
        const full = toward === 1 ? COUNT_IN_MS : COUNT_OUT_MS;
        const duration = Math.max(120, full * Math.abs(toward - from));
        const started = window.performance.now();

        const step = (now) => {
            const t = Math.min(1, (now - started) / duration);
            this.progress = from + (toward - from) * easeOutCubic(t);
            this._paint();

            if (t < 1) {
                this.raf = window.requestAnimationFrame(step);
            } else {
                this.raf = null;
                this.progress = toward;
                this._paint();   // land on the exact figure, not a rounding of it
            }
        };
        this.raf = window.requestAnimationFrame(step);
    },

    /**
     * @private
     */
    _paint() {
        this.figures.forEach((f) => {
            f.el.textContent = f.format(Math.round(f.target * this.progress));
        });
    },
});


})(window.publicWidget);
